ALTER TABLE public.profiles ADD COLUMN study_year integer; ALTER TABLE public.profiles ADD COLUMN department_id uuid REFERENCES public.departments(id); ALTER TABLE public.departments ADD COLUMN campus text; ALTER TABLE public.departments ADD COLUMN source_url text; COMMENT ON COLUMN public.profiles.grad_year IS 'DEPRECATED: replaced by study_year'; COMMENT ON COLUMN public.profiles.studying_course_id IS 'DEPRECATED: communities replace study rooms'; COMMENT ON COLUMN public.profiles.studying_until IS 'DEPRECATED: communities replace study rooms';
GRANT INSERT ON public.institutions, public.departments, public.courses TO authenticated;
CREATE POLICY "contribute colleges" ON public.institutions FOR INSERT TO authenticated WITH CHECK (char_length(trim(name)) BETWEEN 2 AND 150);
CREATE POLICY "contribute departments" ON public.departments FOR INSERT TO authenticated WITH CHECK (char_length(trim(name)) BETWEEN 2 AND 200);
CREATE POLICY "contribute courses" ON public.courses FOR INSERT TO authenticated WITH CHECK (char_length(trim(name)) BETWEEN 2 AND 200);
CREATE TABLE public.communities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 80), slug text UNIQUE NOT NULL CHECK(slug ~ '^[a-z0-9-]{2,80}$'), description text NOT NULL DEFAULT '', institution_id uuid REFERENCES public.institutions(id), creator_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.communities TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.communities TO authenticated; GRANT ALL ON public.communities TO service_role;
ALTER TABLE public.communities ENABLE ROW LEVEL SECURITY;
CREATE POLICY "communities readable" ON public.communities FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "create own community" ON public.communities FOR INSERT TO authenticated WITH CHECK(creator_id=auth.uid());
CREATE POLICY "edit own community" ON public.communities FOR UPDATE TO authenticated USING(creator_id=auth.uid()) WITH CHECK(creator_id=auth.uid());
CREATE TABLE public.community_members (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(community_id,user_id));
GRANT SELECT ON public.community_members TO anon; GRANT SELECT,INSERT,DELETE ON public.community_members TO authenticated; GRANT ALL ON public.community_members TO service_role;
ALTER TABLE public.community_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members readable" ON public.community_members FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "join as self" ON public.community_members FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY "leave as self" ON public.community_members FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.question_communities(question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE,community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE,PRIMARY KEY(question_id,community_id));
GRANT SELECT ON public.question_communities TO anon; GRANT SELECT,INSERT,DELETE ON public.question_communities TO authenticated; GRANT ALL ON public.question_communities TO service_role;
ALTER TABLE public.question_communities ENABLE ROW LEVEL SECURITY;
CREATE POLICY "post communities readable" ON public.question_communities FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "tag own post community" ON public.question_communities FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.questions q WHERE q.id=question_id AND q.author_id=auth.uid()));
CREATE POLICY "remove own community tag" ON public.question_communities FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.questions q WHERE q.id=question_id AND q.author_id=auth.uid()));
CREATE TABLE public.question_votes(question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(question_id,user_id));
GRANT SELECT ON public.question_votes TO anon; GRANT SELECT,INSERT,DELETE ON public.question_votes TO authenticated; GRANT ALL ON public.question_votes TO service_role;
ALTER TABLE public.question_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "post votes readable" ON public.question_votes FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "upvote as self" ON public.question_votes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY "unvote as self" ON public.question_votes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.notification_preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,enabled boolean NOT NULL DEFAULT true,courses boolean NOT NULL DEFAULT true,communities boolean NOT NULL DEFAULT true,campus boolean NOT NULL DEFAULT false,push_enabled boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.notification_preferences TO authenticated; GRANT ALL ON public.notification_preferences TO service_role;
ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own preferences read" ON public.notification_preferences FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "own preferences insert" ON public.notification_preferences FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY "own preferences update" ON public.notification_preferences FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.push_devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,token text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_devices TO authenticated; GRANT ALL ON public.push_devices TO service_role;
ALTER TABLE public.push_devices ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own push devices" ON public.push_devices FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.post_references(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE,answer_id uuid REFERENCES public.answers(id) ON DELETE CASCADE,owner_id uuid NOT NULL REFERENCES public.profiles(id),path text NOT NULL,name text NOT NULL,mime_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.post_references TO anon; GRANT SELECT,INSERT,DELETE ON public.post_references TO authenticated; GRANT ALL ON public.post_references TO service_role;
ALTER TABLE public.post_references ENABLE ROW LEVEL SECURITY;
CREATE POLICY "references readable" ON public.post_references FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "attach as author" ON public.post_references FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND split_part(path,'/',1)=auth.uid()::text AND ((answer_id IS NULL AND EXISTS(SELECT 1 FROM public.questions q WHERE q.id=question_id AND q.author_id=auth.uid())) OR EXISTS(SELECT 1 FROM public.answers a WHERE a.id=answer_id AND a.question_id=post_references.question_id AND a.author_id=auth.uid())));
CREATE POLICY "remove own reference" ON public.post_references FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE POLICY "reference files readable" ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='references' AND EXISTS(SELECT 1 FROM public.post_references r WHERE r.path=name));
CREATE POLICY "upload own reference file" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='references' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "delete own reference file" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='references' AND (storage.foldername(name))[1]=auth.uid()::text);
ALTER TABLE public.notifications ADD COLUMN push_sent_at timestamptz;
CREATE OR REPLACE FUNCTION public.filter_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.notification_preferences p WHERE p.user_id=NEW.user_id AND NOT p.enabled) THEN RETURN NULL; END IF; RETURN NEW; END; $$;
CREATE TRIGGER notification_preferences_filter BEFORE INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.filter_notification();
CREATE OR REPLACE FUNCTION public.notify_post_followers() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.accepted_answer_id IS NOT NULL AND NEW.accepted_answer_id IS DISTINCT FROM OLD.accepted_answer_id THEN INSERT INTO public.notifications(user_id,actor_id,type,question_id) SELECT v.user_id,NEW.author_id,'accepted',NEW.id FROM public.question_votes v WHERE v.question_id=NEW.id AND v.user_id<>NEW.author_id AND v.user_id<>(SELECT author_id FROM public.answers WHERE id=NEW.accepted_answer_id); END IF; RETURN NEW; END; $$;
CREATE TRIGGER post_followers_notify AFTER UPDATE OF accepted_answer_id ON public.questions FOR EACH ROW EXECUTE FUNCTION public.notify_post_followers();
CREATE OR REPLACE FUNCTION public.notify_post_audience() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.questions; BEGIN IF TG_TABLE_NAME='questions' THEN q:=NEW; ELSE SELECT * INTO q FROM public.questions WHERE id=NEW.question_id; END IF; INSERT INTO public.notifications(user_id,actor_id,type,question_id) SELECT DISTINCT p.id,q.author_id,'invite',q.id FROM public.profiles p LEFT JOIN public.notification_preferences n ON n.user_id=p.id WHERE p.id<>q.author_id AND COALESCE(n.enabled,true) AND ((TG_TABLE_NAME='questions' AND ((COALESCE(n.campus,false) AND p.institution_id=q.institution_id) OR (COALESCE(n.courses,true) AND EXISTS(SELECT 1 FROM public.enrollments e WHERE e.user_id=p.id AND e.course_id=q.course_id)))) OR (TG_TABLE_NAME='question_communities' AND COALESCE(n.communities,true) AND EXISTS(SELECT 1 FROM public.community_members m JOIN public.question_communities t ON t.community_id=m.community_id WHERE m.user_id=p.id AND t.question_id=q.id))) AND NOT EXISTS(SELECT 1 FROM public.notifications x WHERE x.user_id=p.id AND x.question_id=q.id AND x.type='invite'); RETURN NEW; END; $$;
CREATE TRIGGER new_post_audience AFTER INSERT ON public.questions FOR EACH ROW EXECUTE FUNCTION public.notify_post_audience();
CREATE TRIGGER community_post_audience AFTER INSERT ON public.question_communities FOR EACH ROW EXECUTE FUNCTION public.notify_post_audience();
ALTER TABLE public.profiles ADD CONSTRAINT study_year_range CHECK(study_year IS NULL OR study_year BETWEEN 1 AND 8);
CREATE INDEX post_votes_question_idx ON public.question_votes(question_id); CREATE INDEX post_communities_community_idx ON public.question_communities(community_id);